#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

/**
 * GPE 10468: Maximum Product
 * 題目要求在一組整數序列中，找出連續子序列的最大乘積。
 * 如果最大乘積不是正數，則輸出 0。
 * 由於 N 最大只有 18，我們可以使用 O(N^2) 的暴力法枚舉所有可能的子序列範圍 [i, j]。
 */

int main() {
    int N, caseNum = 1;
    // 持續讀取 N 直到檔案結束
    while (cin >> N) {
        vector<long long> s(N);
        for (int i = 0; i < N; ++i) {
            cin >> s[i];
        }

        long long maxProd = 0;
        // 枚舉子序列的起始點 i
        for (int i = 0; i < N; ++i) {
            long long currentProd = 1;
            // 枚舉子序列的結束點 j
            for (int j = i; j < N; ++j) {
                currentProd *= s[j];
                // 更新最大乘積
                if (currentProd > maxProd) {
                    maxProd = currentProd;
                }
            }
        }

        // 輸出格式：Case #M: The maximum product is P.
        cout << "Case #" << caseNum++ << ": The maximum product is " << maxProd << "." << endl;
        // 每個測試案例後需輸出一個空行
        cout << endl;
    }
    return 0;
}
